create extension if not exists pgcrypto;
create table roles(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null);
create table user_profiles(id uuid primary key references auth.users(id) on delete cascade,user_code text unique not null,full_name text not null,email text not null,role_id uuid references roles(id),active boolean default true,created_at timestamptz default now());
create table document_sequences(document_type text primary key,prefix text not null,next_number bigint default 1,padding int default 6);
create or replace function next_code(p_type text) returns text language plpgsql security definer as $$declare r document_sequences%rowtype;n bigint;begin update document_sequences set next_number=next_number+1 where document_type=p_type returning *,next_number-1 into r,n;if not found then raise exception 'Missing sequence %',p_type;end if;return r.prefix||lpad(n::text,r.padding,'0');end$$;
insert into document_sequences values ('USER','USR-2026-',1,6),('CUSTOMER','CUS-2026-',1,6),('SUPPLIER','SUP-2026-',1,6),('BANK','BNK-2026-',1,6),('INVOICE','INV-2026-',1,6),('RECEIPT','RCT-2026-',1,6),('AP_INVOICE','API-2026-',1,6),('REFUND','RFD-2026-',1,6),('JOURNAL','JRN-2026-',1,6),('APPROVAL','APR-2026-',1,6) on conflict do nothing;
create table erp_customers(id uuid primary key default gen_random_uuid(),customer_code text unique not null default next_code('CUSTOMER'),name text not null,trn text,email text,phone text,status text default 'active',created_by uuid references auth.users(id),created_at timestamptz default now());
create table erp_suppliers(id uuid primary key default gen_random_uuid(),supplier_code text unique not null default next_code('SUPPLIER'),name text not null,trn text,email text,phone text,status text default 'active',created_by uuid references auth.users(id),created_at timestamptz default now());
create table erp_bank_accounts(id uuid primary key default gen_random_uuid(),bank_account_code text unique not null default next_code('BANK'),name text not null,bank_name text,iban text,account_type text,currency text default 'AED');
create table erp_invoices(id uuid primary key default gen_random_uuid(),invoice_code text unique not null default next_code('INVOICE'),customer_id uuid references erp_customers(id),invoice_date date,net_amount numeric(18,2),vat_amount numeric(18,2),total_amount numeric(18,2),status text default 'draft',created_by uuid references auth.users(id),created_at timestamptz default now());
create table erp_receipts(id uuid primary key default gen_random_uuid(),receipt_code text unique not null default next_code('RECEIPT'),customer_id uuid references erp_customers(id),receipt_date date,amount numeric(18,2),status text default 'draft',created_by uuid references auth.users(id),created_at timestamptz default now());
create table erp_ap_invoices(id uuid primary key default gen_random_uuid(),ap_invoice_code text unique not null default next_code('AP_INVOICE'),supplier_id uuid references erp_suppliers(id),invoice_date date,amount numeric(18,2),status text default 'draft',created_by uuid references auth.users(id),created_at timestamptz default now());
create table erp_refunds(id uuid primary key default gen_random_uuid(),refund_code text unique not null default next_code('REFUND'),customer_id uuid references erp_customers(id),amount numeric(18,2),status text default 'draft');
create table erp_journals(id uuid primary key default gen_random_uuid(),journal_code text unique not null default next_code('JOURNAL'),source_type text,source_code text,journal_date date,status text default 'draft');
create table erp_journal_lines(id uuid primary key default gen_random_uuid(),journal_id uuid references erp_journals(id) on delete cascade,line_no int,account_code text,debit numeric(18,2) default 0,credit numeric(18,2) default 0,unique(journal_id,line_no));
create table erp_approvals(id uuid primary key default gen_random_uuid(),approval_code text unique not null default next_code('APPROVAL'),source_type text,source_code text,status text default 'pending');
insert into roles(code,name) values ('ADMIN','System Administrator'),('PREPARER','Preparer'),('FIN_MGR','Finance Manager'),('CONTROLLER','Finance Controller'),('CFO','CFO') on conflict do nothing;
do $$declare t text;begin foreach t in array array['user_profiles','erp_customers','erp_suppliers','erp_bank_accounts','erp_invoices','erp_receipts','erp_ap_invoices','erp_refunds','erp_journals','erp_journal_lines','erp_approvals'] loop execute format('alter table %I enable row level security',t);execute format('create policy auth_%I on %I for all to authenticated using (true) with check (true)',t,t);end loop;end$$;
